            Vec::new(),
            vec![vec![
                GeomSegment::Line { a: 2, b: 3 },
                GeomSegment::Line { a: 3, b: 5 },
                GeomSegment::Line { a: 5, b: 4 },
                GeomSegment::Line { a: 4, b: 2 },
            ]],
        );
        let base_all: Vec<[f64; 2]> = raw.oncurve.clone();
        let ownership = ControlOwnership::prepare(
            &raw,
            &raw,
            &base_all,
            &base_all,
            &[prep(2, 5, 3, 4, &base_all)],
