    }
    for (row, _) in &plain[0..4] {
        assert!(support(row).iter().all(|k| *k == 0 || *k == 1));
    }
    for (row, _) in &plain[4..8] {
        assert!(support(row).iter().all(|k| *k == 2 || *k == 3));
    }
}

