}

fn append(
    gates: &[JointGate],
    base: &[[f64; 2]],
    up: &[[f64; 2]],
    reduce: &impl Fn(&[f64]) -> Vec<f64>,
    seed_rows: Vec<Vec<f64>>,
    seed_bounds: Vec<f64>,
) -> (Vec<Vec<f64>>, Vec<f64>) {
    let mut cmat = seed_rows;
