use super::*;

fn gate(
    j: usize,
    iv: usize,
    ov: usize,
    prev_line: bool,
    seg_line: bool,
    smooth: bool,
) -> JointGate {
    JointGate {
        j,
        iv,
        ov,
        prev_line,
        seg_line,
        smooth,
    }
}

fn identity(row: &[f64]) -> Vec<f64> {
    row.to_vec()
}

fn append(
    gates: &[JointGate],
    base: &[[f64; 2]],
    up: &[[f64; 2]],
    reduce: &impl Fn(&[f64]) -> Vec<f64>,
    seed_rows: Vec<Vec<f64>>,
    seed_bounds: Vec<f64>,
) -> (Vec<Vec<f64>>, Vec<f64>) {
    let mut cmat = seed_rows;
    let mut clower = seed_bounds;
    append_sharp_joint_constraints(gates, base, up, reduce, &mut cmat, &mut clower);
    (cmat, clower)
}

