use super::super::intervals::Contact;
use super::*;

fn portion(i0: usize, i1: usize, t0: f64, t1: f64) -> geometry::Portion {
    geometry::Portion {
        contour: 0,
        seg: 0,
        t0,
        t1,
        p0: [0.0, 0.0],
        p1: [0.0, 0.0],
        i0,
        i1,
        hidden: false,
        unknown: false,
    }
}

fn contact(sa: f64, sb: f64) -> geometry::Station {
    geometry::Station {
        s: 0.0,
        hit: Contact {
            center: [0.0, 0.0],
            qa: [0.0, 0.0],
            qb: [0.0, 0.0],
            r: 0.0,
            width: 0.0,
            sa,
            sb,
        },
    }
}

fn pair(
    a: geometry::Portion,
    b: geometry::Portion,
    stations: Vec<geometry::Station>,
) -> geometry::PreppedPair {
    geometry::PreppedPair {
        id: String::from("t"),
        a,
        b,
        normal: [0.0, 1.0],
        stations,
        src_widths: Vec::new(),
        fit_widths: Vec::new(),
        arc: 0.0,
        span_lo: 0.0,
        span_hi: 0.0,
    }
}

fn rect_pair(stations: Vec<geometry::Station>) -> geometry::PreppedPair {
    pair(portion(0, 1, 0.0, 1.0), portion(2, 3, 0.0, 1.0), stations)
}

