                if !current.is_empty() {
                    contours.push(std::mem::take(&mut current));
                }
                pen = None;
                start = None;
            }
        }
    }
    if !current.is_empty() {
        contours.push(current);
    }
    Ok(Parsed {
        oncurve,
        offcurve,
        contours,
    })
}

