        xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
        ys.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
    );
    for hull in boxes {
        if !bbox_overlap(&bbox, hull) {
            continue;
        }
        let mut clear = true;
        for st in stations {
            if bbox_point_dist(st.hit.center, hull) <= st.hit.r {
                clear = false;
                break;
            }
        }
        if !clear {
            return true;
        }
    }
